function chart(){const bars=liveBars();const stale=bars.length&&(!data.state.candles_received_at||Date.now()-data.state.candles_received_at>30000);const m1=(()=>{const open=data?.state?.positions||[],floating=open.reduce((sum,p)=>sum+Number(p.profit||0),0),lot=open.reduce((sum,p)=>sum+Number(p.volume||0),0),from=bars[0]?.time||0,to=(bars.at(-1)?.time||0)+({M1:60,M5:300,M15:900}[tf]||60),entries=(data?.deals||[]).filter(d=>Number(d.entry)===0&&Number(d.time)>=from&&Number(d.time)<to).length,currency=esc(data?.state?.currency||''),color=floating>=0?'#10d7a0':'#ff4c64';return `<div class="grid g3 chart-mini-stats" style="margin:14px 0"><div style="padding:12px;border:1px solid #223348;border-radius:10px"><small class="sub">RESULTADO FLUTUANTE</small><b style="display:block;margin-top:4px;color:${color}">${floating>=0?'+':''}${num(floating)} ${currency}</b><small class="sub">Posições abertas agora</small></div><div style="padding:12px;border:1px solid #223348;border-radius:10px"><small class="sub">ENTRADAS NO ${tf}</small><b style="display:block;margin-top:4px">${entries}</b><small class="sub">No intervalo exibido</small></div><div style="padding:12px;border:1px solid #223348;border-radius:10px"><small class="sub">LOTE EM POSIÇÃO</small><b style="display:block;margin-top:4px">${num(lot)}</b><small class="sub">${open.length} posição${open.length===1?'':'ões'} aberta${open.length===1?'':'s'}</small></div></div>`;})();return card('Gráfico de candles',`<div class="chart-top"><div class="row chart-toolbar"><div class="tools chart-timeframes">${['M1','M5','M15'].map(t=>`<button data-tf="${t}" class="${tf===t?'active':''}">${t}</button>`).join('')}</div><div class="chart-status"><span class="pill gold">${bars.length?(stale?'Velas desatualizadas':bars.length+' velas recebidas'):'Aguardando dados'}</span><button class="btn chart-expand-desktop" id="toggle-chart-expanded" type="button" aria-pressed="${chartExpanded}">${chartExpanded?'✕ Voltar ao modo normal':'Ampliar gráfico'}</button></div></div>${m1}<div class="row chart-controls" style="margin:14px 0"><button class="btn" id="zoom-out" type="button" ${chartZoom<=1?'disabled':''}>− Zoom</button><span class="pill">Zoom horizontal ${Math.round(chartZoom*100)}%</span><button class="btn" id="zoom-in" type="button" ${chartZoom>=4?'disabled':''}>+ Zoom</button><button class="btn chart-expand-mobile" id="toggle-chart-expanded-mobile" type="button" aria-pressed="${chartExpanded}">${chartExpanded?'Fechar':'↗ Ampliar'}</button><button class="btn" id="follow-candles" type="button" aria-pressed="true">Acompanhando última vela</button></div></div><div class="chartbox" style="height:360px;max-height:360px;overflow:hidden;background:#000">${candleView()}</div><div class="legend"><span><b aria-hidden="true" style="color:#10d7a0">↑</b> Alta / compra</span><span><b aria-hidden="true" style="color:#ff4c64">↓</b> Baixa / venda</span><span><b aria-hidden="true" style="color:#f4bf48">→</b> Saída / reversão</span>${bbOn3?`<span><b aria-hidden="true" style="color:#ff2a2a">━</b> Bollinger 20/3</span>`:''}${bbOn4?`<span><b aria-hidden="true" style="color:#ffe600">━</b> Bollinger 20/4</span>`:''}</div><p class="sub"><b>Escala vertical ${Math.round(chartYScale*100)}%:</b> arraste a régua de preços à direita para esticar ou comprimir as velas. Arraste o centro do gráfico para cima ou para baixo para reposicioná-las. Dê duplo clique na régua para restaurar escala e posição. Use + Zoom e − Zoom para a largura das velas e deslize horizontalmente. Horário da corretora; a última vela pode estar em formação.</p>`,chartExpanded?'chart-panel chart-expanded':'chart-panel');}
